import java.util.concurrent.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class AirportSimulation {
    private static final int MAX_GROUND_CAPACITY = 3;
    private static final int NUM_GATES = 3;
    private static final Semaphore runway = new Semaphore(1, true);
    private static final Semaphore groundCapacity = new Semaphore(MAX_GROUND_CAPACITY, true);
    private static final Semaphore gates = new Semaphore(NUM_GATES, true);
    private static final Semaphore fuelTruck = new Semaphore(1, true);

    private static List<Long> waitingTimes = Collections.synchronizedList(new ArrayList<>());
    private static AtomicInteger totalPlanesServed = new AtomicInteger(0);
    private static AtomicInteger totalPassengers = new AtomicInteger(0);

    static class Airplane extends Thread {
        String id; boolean isEmergency;
        long requestTime;

        Airplane(String id, boolean isEmergency) {
            this.id = id; this.isEmergency = isEmergency;
        }

        public void run() {
            try {
                requestTime = System.currentTimeMillis();
                System.out.println(id + (isEmergency ? " (EMERGENCY)" : "") + " requesting landing.");

                if (!isEmergency) groundCapacity.acquire();
                else System.out.println(id + " bypassing queue due to emergency!");

                runway.acquire();
                waitingTimes.add(System.currentTimeMillis() - requestTime);
                System.out.println(id + " landing on runway.");
                Thread.sleep(500);
                runway.release();

                gates.acquire();
                System.out.println(id + " docked at gate.");

                Thread cleaning = new Thread(() -> { try { Thread.sleep(1000); } catch(Exception e) {} });
                cleaning.start();

                fuelTruck.acquire();
                System.out.println(id + " refuelling.");
                Thread.sleep(800);
                fuelTruck.release();

                cleaning.join();
                int passengers = new Random().nextInt(100) + 50;
                totalPassengers.addAndGet(passengers);
                System.out.println(id + " boarding " + passengers + " passengers.");
                Thread.sleep(1000);

                gates.release();
                runway.acquire();
                System.out.println(id + " taking off.");
                Thread.sleep(500);
                runway.release();

                if (!isEmergency) groundCapacity.release();
                totalPlanesServed.incrementAndGet();
                System.out.println(id + " left the airport.");
            } catch (Exception e) {}
        }
    }

    public static void main(String[] args) throws InterruptedException {
        // Simulated congested scenario
        new Airplane("Plane_Gate1", false).start();
        new Airplane("Plane_Gate2", false).start();
        Thread.sleep(200);
        new Airplane("Waiting_1", false).start();
        new Airplane("Waiting_2", false).start();
        Thread.sleep(500);
        new Airplane("EMERGENCY_3", true).start();

        Thread.sleep(10000);
        System.out.println("\n--- ATC Statistics ---");
        System.out.println("Planes Served: " + totalPlanesServed.get());
        System.out.println("Total Passengers: " + totalPassengers.get());
        long max = waitingTimes.stream().max(Long::compare).orElse(0L);
        double avg = waitingTimes.stream().mapToLong(Long::longValue).average().orElse(0.0);
        System.out.println("Max Wait: " + max + "ms, Avg Wait: " + avg + "ms");
    }
}
